-- Additive managed-app roles and isolated shared preview rows. Existing permissions stay private-only.
CREATE TABLE IF NOT EXISTS preview_app_roles(project_id TEXT NOT NULL,user_id TEXT NOT NULL,role TEXT NOT NULL CHECK(role='admin'),created_at INTEGER NOT NULL,PRIMARY KEY(project_id,user_id),FOREIGN KEY(project_id,user_id) REFERENCES preview_app_users(project_id,id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS preview_backend_rows(project_id TEXT NOT NULL REFERENCES previews(id) ON DELETE CASCADE,table_name TEXT NOT NULL,id TEXT NOT NULL,data_json TEXT NOT NULL,created_at INTEGER NOT NULL,PRIMARY KEY(project_id,table_name,id));
CREATE TRIGGER preview_shared_capacity BEFORE INSERT ON preview_backend_rows WHEN (SELECT count(*) FROM preview_backend_rows)>=20000 BEGIN SELECT RAISE(ABORT,'target_service_capacity'); END;
CREATE TRIGGER preview_shared_active BEFORE INSERT ON preview_backend_rows WHEN NOT EXISTS(SELECT 1 FROM previews WHERE id=NEW.project_id AND status NOT IN ('stopped','expired','timed_out') AND expires_at>CAST((julianday('now')-2440587.5)*86400000 AS INTEGER)) BEGIN SELECT RAISE(ABORT,'preview_expired'); END;
CREATE TRIGGER preview_shared_update_active BEFORE UPDATE ON preview_backend_rows WHEN NOT EXISTS(SELECT 1 FROM previews WHERE id=NEW.project_id AND status NOT IN ('stopped','expired','timed_out') AND expires_at>CAST((julianday('now')-2440587.5)*86400000 AS INTEGER)) BEGIN SELECT RAISE(ABORT,'preview_expired'); END;
ALTER TABLE private_build_grants ADD COLUMN managed_data INTEGER NOT NULL DEFAULT 0;
DROP TRIGGER private_build_approve;
CREATE TRIGGER private_build_approve BEFORE UPDATE OF status ON private_build_packages BEGIN
 SELECT RAISE(ABORT,'private_build_terminal') WHERE OLD.status<>'pending';
 SELECT RAISE(ABORT,'private_build_stale_or_revoked') WHERE NEW.status='approved' AND NOT EXISTS(SELECT 1 FROM projects p JOIN memberships m ON m.workspace_id=p.workspace_id JOIN proposals s ON s.id=NEW.source_proposal JOIN backend_proposals b ON b.id=NEW.backend_proposal JOIN mcp_access_tokens t ON t.client_id=NEW.client_id AND t.project_id=NEW.project_id AND t.user_id=NEW.owner_id JOIN mcp_clients c ON c.id=NEW.client_id WHERE p.id=NEW.project_id AND p.revision=NEW.base_revision AND m.user_id=NEW.owner_id AND m.role='owner' AND s.status='pending' AND s.project_id=p.id AND s.base_revision=p.revision AND b.status='pending' AND b.project_id=p.id AND c.project_id=p.id AND c.owner_id=NEW.owner_id AND c.revoked_at IS NULL AND t.client_id=c.id AND t.project_id=p.id AND t.user_id=NEW.owner_id AND t.revoked_at IS NULL AND t.expires_at>NEW.decided_at AND EXISTS(SELECT 1 FROM json_each(t.scopes) WHERE value='sandbox.write') AND EXISTS(SELECT 1 FROM json_each(t.scopes) WHERE value='schema.propose') AND EXISTS(SELECT 1 FROM json_each(t.scopes) WHERE value='checks.run') AND EXISTS(SELECT 1 FROM json_each(t.scopes) WHERE value='preview.create') AND json_extract(b.config_json,'$.version') IN (2,3) AND NEW.base_backend_digest IS COALESCE((SELECT digest FROM backend_proposals WHERE project_id=p.id AND status='approved' ORDER BY decided_at DESC,id DESC LIMIT 1),(SELECT digest FROM project_backends WHERE project_id=p.id)));
 SELECT RAISE(ABORT,'private_build_grant_revoked') WHERE NEW.status='approved' AND NEW.grant_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM private_build_grants g JOIN mcp_access_tokens t ON t.id=NEW.token_id WHERE g.id=NEW.grant_id AND g.project_id=NEW.project_id AND g.client_id=NEW.client_id AND g.owner_id=NEW.owner_id AND g.revoked_at IS NULL AND ((SELECT json_extract(config_json,'$.version') FROM backend_proposals WHERE id=NEW.backend_proposal)=2 OR g.managed_data=1) AND EXISTS(SELECT 1 FROM json_each(t.scopes) WHERE value='sandbox.write') AND EXISTS(SELECT 1 FROM json_each(t.scopes) WHERE value='schema.propose') AND EXISTS(SELECT 1 FROM json_each(t.scopes) WHERE value='checks.run') AND EXISTS(SELECT 1 FROM json_each(t.scopes) WHERE value='preview.create'));
END;
